#!/usr/bin/env bash
# Park Pilot als eigene App (ohne Browser): erzeugt das Android-Projekt im Ordner "android-app"
# und packt das Spiel aus dem Ordner "parkpilot/" fest in die APK. Online-Funktionen
# (Anmeldung, Cloud-Spielstand, Multiplayer, Spiel-Updates) laufen weiter uebers Internet.
# Wird automatisch vom GitHub-Bauauftrag "Park Pilot App" ausgefuehrt. Nicht von Hand aendern.
set -euo pipefail
# Spieldateien: direkt im Repo (eigenes Repo) oder im Unterordner parkpilot/
if [ -f index.html ]; then SRC=.; elif [ -f parkpilot/index.html ]; then SRC=parkpilot; else
  echo "FEHLER: index.html fehlt im Repo. Bitte zuerst die Spieldateien hochladen."; exit 1
fi
rm -rf android-app && mkdir -p android-app
base64 -d > /tmp/pp-app.tgz <<'B64'
