B64
tar -xzf /tmp/pp-app.tgz -C android-app
A=android-app/app/src/main/assets
mkdir -p "$A/fb"
for f in index.html version.json firebase-config.js manifest.webmanifest icon-192.png icon-512.png icon-maskable-512.png; do
  [ -f "$SRC/$f" ] && cp "$SRC/$f" "$A/"
done
# Versionsnummer (fuer automatische Spiel-Updates)
if [ ! -f "$A/version.json" ]; then
  V=$(grep -o 'VER="[0-9.]*"' "$A/index.html" | head -1 | cut -d'"' -f2)
  printf '{"v":"%s"}\n' "${V:-1.0}" > "$A/version.json"
fi
OWNER="$(echo "${GITHUB_REPOSITORY_OWNER:-example}" | tr 'A-Z' 'a-z')"
REPO="$(echo "${GITHUB_REPOSITORY:-x/parkpilot}" | cut -d/ -f2 | tr 'A-Z' 'a-z')"
if [ "$SRC" = "." ] && [ "$REPO" != "$OWNER.github.io" ]; then SITE="https://$OWNER.github.io/$REPO/"; else SITE="https://$OWNER.github.io/parkpilot/"; fi
printf '{"site":"%s"}\n' "$SITE" > "$A/app.json"
# Firebase-Bausteine (Login, Datenbank, Multiplayer) direkt in die App packen
FBV=10.12.2
for m in app auth database; do
  curl -fsSL --retry 3 -o "$A/fb/firebase-$m-compat.js" "https://www.gstatic.com/firebasejs/$FBV/firebase-$m-compat.js" \
    || echo "Hinweis: firebase-$m nicht geladen, die App holt es dann online."
done
echo "App-Projekt erzeugt:"; cat "$A/version.json" "$A/app.json"; ls -la "$A" "$A/fb"
